import sys

class compiler:
    def __init__(self,pgm:list,ADDR_IN=254,ADDR_OUT=255):
        self.pgm=pgm
        self.mem=[0 for _ in range(256)]
        self.buff=[]
        self.error=[]
        self.addr_in=ADDR_IN
        self.addr_out=ADDR_OUT

    def next_line(self):
        l=[]
        while l==[]:
            if len(self.pgm) == 0:
                return None
            l=self.pgm.pop(0)
            l=l.strip()
            l=l.replace(':',': ')
            l=l.replace(',',' , ')
            l=l.replace('+',' + ')
            l=l.split()
            l=list(filter(lambda x:x!='',l))
        return l

    def next_token(self,error=True):
        if len(self.buff)==0:
            l=self.next_line()
            if not l:
                if error:
                    self.error.append("Error: token expected")
                return None
            self.buff+=l
        v=self.buff.pop(0)
        if v:
            v=v.upper()
        else:
            pass
        return v

    def peek_token(self):
        # end of program is not an error when peeking (e.g. subleq without C on the last line)
        t=self.next_token(False)
        if t is not None:
            self.buff=[t]+self.buff
        return t

    def add(self,val):
        if self.addr>=self.addr_in:
            self.error.append("Error: program too large")
            return
        self.mem[self.addr]=val
        self.addr+=1

    def nextint(self):
        v=self.next_token()
        return self.readint(v)

    def readint(self,v):
        try:
            vint=int(v)
        except:
            if v.startswith("@"):
                offset = 0
                plus=self.peek_token()
                if plus=='+':
                    plus = self.next_token()
                    offset=int(self.next_token())
                if v in self.labels:
                    vint=self.labels[v]+offset
                else:
                    vint=f"{v}+{offset}"
        # trasformare complemento a 2
        if isinstance(vint,int):
            vint=vint%256 # neg=256+vint
        return vint

    def first_pass(self):
        while len(self.error)==0:
            i=self.next_token(False)
            if not i:
                break
            if i.startswith('@') and i.endswith(':'):
                lab=i[:-1]
                if lab not in self.labels:
                    self.labels[lab]=self.addr
                else:
                    self.error.append(f"Error: label [{lab}] already defined")
            elif i=='SUBLEQ':
                a=self.nextint()
                comma=self.next_token()
                if comma!=',':
                    self.error.append("Error: missing comma")
                b=self.nextint()
                f=self.peek_token()
                if f==',':
                    f=self.next_token()
                    c=self.nextint()
                else:
                    c=self.addr+3
                self.add(a)
                self.add(b)
                self.add(c)
            elif i=='.DATA':
                v=self.nextint()
                self.add(v)
            else:
                self.error.append(f"Error: unknown symbol [{i}]")

    def second_pass(self):
        if len(self.error)>0:
            return
        for addr,m in enumerate(self.mem):
            if isinstance(m,str):
                lab,off=m.split('+')
                if lab not in self.labels:
                    self.error.append(f"Error: unknown label [{lab}]")
                else:
                    self.buff=['+',off]
                    v=self.readint(lab)
                    self.mem[addr]=v

    def compile(self)->list:
        self.addr=0
        self.labels={'@IN':self.addr_in,'@OUT':self.addr_out}
        self.first_pass()
        self.second_pass()
        if len(self.error)>0:
            return None
        else:
            return self.mem

class VM:
    def __init__(self,mem,IN,ADDR_IN=254,ADDR_OUT=255):
        self.mem=mem
        self.IN=IN
        self.OUT=[]
        self.halt=False
        self.addr=0
        self.addr_in=ADDR_IN
        self.addr_out=ADDR_OUT

    def debug(self,arg):
        print(arg,file=sys.stderr)

    def peek(self,addr):
        if addr==self.addr_in:
            if len(self.IN)>0:
                v=self.IN.pop(0)
                self.debug(f"[<=] reading {v} from IN")
            else:
                v=0
                self.debug(f"[!] IN empty, Halt")
                self.halt=True
        elif addr==self.addr_out:
            v=0
            self.debug(f"[+] reading 0 from OUT")
        else:
            v=self.mem[addr]
            self.debug(f"[+] reading {v} from mem[{addr}]")
        return v

    def poke(self,addr,v):
        if addr==self.addr_in:
            self.debug(f"[+] writing {v} to IN. ignored")
        elif addr==self.addr_out:
            self.debug(f"[=>] output {v}")
            self.OUT.append(v)
        else:
            self.mem[addr]=v
            self.debug(f"[+] writing {v} to mem[{addr}]")
        return v

    def run(self):
        while not self.halt:
            a,b,c=[(self.addr+k)%256 for k in range(3)]
            mema=self.mem[a]
            memb=self.mem[b]
            memc=self.mem[c]
            ca=self.peek(mema)
            if self.halt:
                break  # input exhausted: the instruction is aborted, nothing is written
            cb=self.peek(memb)
            if self.halt:
                break
            newa=ca-cb
            newa=newa%256
            self.poke(mema,newa)
            self.debug(f"{a:02x} subleq {mema},{memb},{memc}")
            if newa>=128 or newa==0:
                self.addr=memc
                self.debug(f"[JP] {newa-256}({newa})<=0, jump to {self.addr}")
            else:
                self.addr=(self.addr+3)%256
            if self.addr in [self.addr_in,self.addr_out]:
                self.debug(f"[!] Halt")
                self.halt=True
        return self.OUT

class OISC:
    def __init__(self,pgm:str,IN:str):
        self.pgm=pgm.split("\n")
        self.IN = list(map(int, IN.split(',')))
        self.OUT=[]

    def get_out(self):
        self.OUT=list(map(str,self.OUT))
        return '\n'.join(self.OUT)

    def dump(self,mem):
        for k in range(16):
            print(f"{k * 16:02x}:", file=sys.stderr, end='')
            for i in range(16):
                r=mem[k*16+i]
                if isinstance(r,int):
                    print(f" {mem[k*16+i]:02x}",file=sys.stderr,end='')
                else:
                    print(f" {mem[k * 16 + i]}", file=sys.stderr, end='')
            print(f"", file=sys.stderr)

    def run(self):
        ain=254
        aout=ain+1
        c=compiler(self.pgm,ain,aout)
        self.mem=c.compile()
        if not self.mem:
            return c.error[0]
        self.dump(self.mem)
        vm=VM(self.mem,self.IN,ain,aout)
        self.OUT=vm.run()
        return self.get_out()

if __name__ == '__main__':
    n=int(input())
    IN=input()
    pgm=[]
    for i in range(n):
        pgm.append(input())
    pgm='\n'.join(pgm)
    s=OISC(pgm,IN)
    print(s.run())

